async function loadPeriod(){const token=++loadToken;const pid=$('period').value;const period=historyIndex.periods.find(p=>'archive:'+p.id===pid);if(mode!=='real'||imported||!period){render();return}archiveData={...empty(),period};render();const path=period.files[$('region').value];if(!path)return;try{let next=archiveCache.get(path);if(!next){const res=await fetch('./'+path,{cache:'no-store'});if(!res.ok)throw Error('history');next=validate(await res.json());archiveCache.set(path,next)}if(token!==loadToken)return;archiveData=next;render()}catch{if(token===loadToken)$('periodNote').textContent+=' · 과거 파일을 불러오지 못했습니다. 다시 선택해 주세요.'}}
